interface Entry {
    certificate: Certificate;
    filename: string;
    /** Lazily cached result of `exploreCertificate(certificate)`. */
    info?: CertificateInternals;
}

/** Return the cached `info` or compute and cache it. */
function getOrComputeInfo(entry: Entry): CertificateInternals {
    if (!entry.info) {
        entry.info = exploreCertificate(entry.certificate);
    }
    return entry.info;
}

interface CRLEntry {
    crlInfo: CertificateRevocationListInfo;
    filename: string;
}
interface CRLData {
    serialNumbers: { [key: string]: Date };
    crls: CRLEntry[];
}
interface Thumbs {
    trusted: Map<string, Entry>;
    rejected: Map<string, Entry>;
    issuers: {
        certs: Map<string, Entry>;
    };
    /** key = subjectFingerPrint of issuer certificate */
    crl: Map<string, CRLData>;
    /** key = subjectFingerPrint of issuer certificate */
    issuersCrl: Map<string, CRLData>;
}

/**
 * Identifies which PKI sub-store a certificate event originated from.
 */
export type CertificateStore = "trusted" | "rejected" | "issuersCerts";

/**
 * Identifies which PKI sub-store a CRL event originated from.
 */
export type CrlStore = "crl" | "issuersCrl";

/**
 * Events emitted by {@link CertificateManager} when the
 * file-system watchers detect certificate or CRL changes.
 */
export interface CertificateManagerEvents {
    /** A certificate file was added to a store. */
    certificateAdded: (event: { store: CertificateStore; certificate: Certificate; fingerprint: string; filename: string }) => void;
    /** A certificate file was removed from a store. */
    certificateRemoved: (event: { store: CertificateStore; fingerprint: string; filename: string }) => void;
    /** A certificate file was modified in a store. */
    certificateChange: (event: {
        store: CertificateStore;
        certificate: Certificate;
        fingerprint: string;
        filename: string;
    }) => void;
    /** A CRL file was added. */
    crlAdded: (event: { store: CrlStore; filename: string }) => void;
    /** A CRL file was removed. */
    crlRemoved: (event: { store: CrlStore; filename: string }) => void;
}

/**
 * Options controlling certificate validation in
 * {@link CertificateManager.addTrustedCertificateFromChain}.
 *
 * By default all checks are **strict** (secure). Set individual
 * flags to `true` only in test/development environments.
 */
export interface AddCertificateValidationOptions {
    /**
     * Accept certificates whose validity period has expired
     * or is not yet active.
     * @defaultValue false
     */
    acceptExpiredCertificate?: boolean;

    /**
     * Accept certificates that have been revoked by their
     * issuer's CRL.  When `false` (the default), a revoked
     * certificate is rejected with `BadCertificateRevoked`.
     * @defaultValue false
     */
    acceptRevokedCertificate?: boolean;

    /**
     * Do not fail when a CRL is missing for an issuer in the
     * chain.  When `false` (the default), a missing CRL causes
     * `BadCertificateRevocationUnknown`.
     * @defaultValue false
     */
    ignoreMissingRevocationList?: boolean;

    /**
     * Maximum depth of the certificate chain (leaf + issuers).
     * The leaf certificate counts as depth 1.
     * @defaultValue 5
     */
    maxChainLength?: number;
}

/**
 * Options for creating a {@link CertificateManager}.
 */
export interface CertificateManagerOptions {
    /**
     * RSA key size for generated private keys.
     * @defaultValue 2048
     */
    keySize?: KeySize;
    /** Filesystem path where the PKI directory structure is stored. */
    location: string;

    /**
     * Validation options applied by
     * {@link CertificateManager.addTrustedCertificateFromChain}.
     *
     * Defaults are secure — all checks enabled.
     */
    addCertificateValidationOptions?: AddCertificateValidationOptions;

    /**
     * When `true`, the CertificateManager will **not** start
     * chokidar file-system watchers on the PKI folders.
     *
     * The initial file-system scan still runs so the in-memory
     * indexes are populated, but live change detection is
     * disabled.  This is useful in test / CI environments where
     * many CertificateManager instances are created in parallel
     * and the accumulated `fs.watch` handles exhaust the libuv
     * thread-pool, causing event-loop starvation.
     *
     * @defaultValue false
     */
    disableFileWatchers?: boolean;

    /**
     * Encrypt the private key at rest with this passphrase (opt-in,
     * default off). When set:
     * - a freshly generated key is written as encrypted PKCS#8;
     * - an existing *plaintext* key is re-encrypted in place by
     *   {@link CertificateManager.initialize} (atomic rename, same as
     *   {@link CertificateManager.reencryptPrivateKey}), so enabling the
     *   option on an existing install never leaves the key in cleartext;
     * - an existing encrypted key requires the same passphrase — a
     *   mismatch, or an encrypted key with no passphrase configured, fails
     *   `initialize()` closed with `PrivateKeyPassphraseRequiredError`.
     *
     * A function is called at most once per `CertificateManager` instance
     * (the decrypted key is cached in memory for the instance's lifetime,
     * see {@link CertificateManager.getPrivateKey}). Never logged.
     *
     * Existing consumers that read `own/private/private_key.pem` directly
     * (e.g. node-opcua's `OPCUAServer`, or `createPFX` without its
     * `privateKeyPassphrase` option) still expect a plaintext key — do not
     * enable this unless every reader of that file goes through
     * {@link CertificateManager.getPrivateKey} or is given the passphrase.
     */
    privateKeyPassphrase?: PrivateKeyPassphrase;

    /**
     * Source the private key from somewhere other than
     * `own/private/private_key.pem` (an HSM, a KMS, ...). When set, it
     * overrides disk entirely for every operation that needs the private
     * key — the on-disk file is not read, and `privateKeyPassphrase` is
     * ignored.
     */
    privateKeyProvider?: PrivateKeyProvider;

    /**
     * Use a private key this manager can never read: an opaque
     * {@link IKeyOperations} provider (HSM, KMS, TPM, OS keystore, ...).
     *
     * The distinction with `privateKeyProvider` matters: a
     * `privateKeyProvider` *sources raw key material* from elsewhere and
     * hands it back; `keyOperations` never reveals the key — only sign and
     * decrypt operations on it. Prefer `keyOperations` whenever the key
     * does not need to be exportable.
     *
     * When set:
     * - {@link CertificateManager.getPrivateKey} and
     *   {@link CertificateManager.reencryptPrivateKey} throw
     *   `PrivateKeyUnavailableError` — there is no key material to return
     *   or rewrite, and no on-disk key is generated or expected;
     * - {@link CertificateManager.getKeyOperations} returns this object;
     * - `initialize()` fails closed if the provider cannot answer
     *   `getKeyMetadata()` (unreachable HSM, misconfiguration);
     * - mutually exclusive with `privateKeyProvider` and
     *   `privateKeyPassphrase` — both describe key *material*, which an
     *   opaque configuration does not have.
     */
    keyOperations?: IKeyOperations;
}

